insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c21-grammar','c2-semantic-precision','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Различаем пресуппозицию, импликатуру и намеренную недосказанность',14,'🧠','Смысловая точность','[["Смысл за пределами слов","Пресуппозиция считается уже принятой предпосылкой, а импликатура выводится из контекста и принципов сотрудничества. Проверяй, что именно сказано, что предполагается и что лишь вероятно подразумевается."],["Точная переформулировка","При медиации отмечай степень уверенности: autor stwierdza, sugeruje, zdaje się zakładać. Не превращай намёк в утверждение и сохраняй продуктивную неоднозначность, если она существенна."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',293,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
