insert into public.lessons(id,topic_id,kind,title,plan_title,subtitle,description,minutes,emoji,theory_title,theory_sections,source_metadata,position,is_active) values ('c22-grammar','c2-rhetorical-strategy','grammar','Точность конструкции','Точность конструкции','6 заданий · целевой C2','Управляем перспективой, темпом и силой аргумента без манипуляции',14,'🎙️','Риторическая стратегия','[["Композиция как аргумент","Порядок доводов, повтор и синтаксический параллелизм направляют внимание. Сильная композиция делает логику видимой; она не должна подменять доказательство эмоциональным эффектом."],["Риторика без манипуляции","Предвосхищай сильнейший контраргумент, называй ограничения и проверяй ложные дилеммы. Этическая стратегия усиливает тезис прозрачностью, а не сокрытием неудобных данных."]]','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target"}',298,true) on conflict(id) do update set topic_id=excluded.topic_id,kind=excluded.kind,title=excluded.title,plan_title=excluded.plan_title,subtitle=excluded.subtitle,description=excluded.description,minutes=excluded.minutes,emoji=excluded.emoji,theory_title=excluded.theory_title,theory_sections=excluded.theory_sections,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
