insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-grammar','Составьте: Автор лишь намекает, что решение было принято раньше.','["Autor jedynie sugeruje, że decyzję podjęto wcześniej.","Autor potwierdza decyzję bez żadnych zastrzeżeń.","Decyzja wcześniej autora jedynie sugeruje."]',0,'Jedynie sugeruje точно маркирует вывод, а не подтверждённый факт.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-quiz','Co w tym kontekście znaczy „presupozycja”?','["пресуппозиция","импликатура, подразумеваемый смысл","недосказанность"]',0,'„presupozycja” oznacza tutaj: пресуппозиция.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-reading-check','Które dwa odczytania wypowiedzi pojawiły się wśród słuchaczy?','["Ostrożna pochwała i elegancka rezerwa","Zgoda i odmowa głosowania","Opis kosztów i harmonogramu"]',0,'Оба прочтения прямо названы в первом абзаце.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-grammar','Составьте: Мы меняем не цель, а способ её достижения.','["Nie zmieniamy celu, lecz sposób jego osiągnięcia.","Zmieniamy cel i pomijamy sposób.","Sposób celu nie zmieniamy osiągnięcia."]',0,'Конструкция nie..., lecz... создаёт точную антитезу.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-quiz','Co w tym kontekście znaczy „figura retoryczna”?','["риторическая фигура","смысловой центр","градация"]',0,'„figura retoryczna” oznacza tutaj: риторическая фигура.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-reading-check','Dlaczego pierwsza wersja wystąpienia była problematyczna?','["Tworzyła pozorny dylemat","Nie zawierała żadnych danych","Dotyczyła innego miasta"]',0,'Она сводила аудиторию к сторонникам действия и мнимым защитникам хаоса.',0,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-grammar','Составьте: Из контекста следует, что адресат знал об изменении.','["Z kontekstu wynika, że adresat wiedział o zmianie.","Adresat zmianę z kontekstu wiedzieć powinien.","Kontekst zaprzecza wiedzy adresata o zmianie."]',0,'Конструкция wynikać z + dopełniacz вводит контекстуальный вывод.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-quiz','Co w tym kontekście znaczy „implikatura”?','["импликатура, подразумеваемый смысл","недосказанность","многозначность"]',0,'„implikatura” oznacza tutaj: импликатура, подразумеваемый смысл.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-reading-check','Co presuponowała wypowiedź według językoznawczyni?','["Wspólną znajomość projektu","Jednomyślność komisji","Brak kosztów"]',0,'Пресуппозицией была общая осведомлённость о проекте.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-grammar','Составьте: Даже если возражение верно, оно не опровергает главного вывода.','["Nawet jeśli zarzut jest trafny, nie obala głównego wniosku.","Zarzut trafny obala zawsze każdy wniosek.","Główny wniosek nawet zarzut jeśli."]',0,'Nawet jeśli вводит уступку без отказа от основного вывода.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-quiz','Co w tym kontekście znaczy „punkt ciężkości”?','["смысловой центр","градация","антитеза"]',0,'„punkt ciężkości” oznacza tutaj: смысловой центр.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-reading-check','Jak redaktorka odwróciła perspektywę?','["Porównała trzy warianty, koszty i skutki","Usunęła wszystkie argumenty","Zastąpiła wystąpienie reklamą"]',0,'Вместо бинарного выбора предложено сравнение вариантов.',1,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-grammar','Które zdanie oddziela treść dosłowną od wniosku?','["Dosłownie autor mówi o kosztach; pośrednio podważa sens reformy.","Autor na pewno odrzuca reformę.","Koszty są reformą."]',0,'Первая формулировка отдельно называет буквальный и выводимый уровни смысла.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-quiz','Co w tym kontekście znaczy „niedopowiedzenie”?','["недосказанность","многозначность","буквальность"]',0,'„niedopowiedzenie” oznacza tutaj: недосказанность.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-reading-check','Jak wcześniejsza rozmowa o kosztach wpłynęła na interpretację?','["Wzmocniła krytyczne odczytanie, ale go nie dowiodła","Całkowicie je obaliła","Nie miała żadnego związku"]',0,'Контекст повысил правдоподобие, но не сделал вывод доказанным.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-grammar','Które zdanie stosuje paralelizm bez pustego patosu?','["Potrzebujemy danych, potrzebujemy czasu, potrzebujemy odpowiedzialności.","Potrzebujemy wszystkiego i natychmiast.","Dane są, jakie są."]',0,'Повтор одной структуры создаёт параллелизм и сохраняет содержательные опоры.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-quiz','Co w tym kontekście znaczy „gradacja”?','["градация","антитеза","синтаксический параллелизм"]',0,'„gradacja” oznacza tutaj: градация.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-reading-check','Czemu służył paralelizm w nowej wersji?','["Zachowaniu rytmu przy jasnej strukturze kontroli","Ukryciu kosztów","Ośmieszeniu przedsiębiorców"]',0,'Повтор организовал три проверяемых шага.',2,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-grammar','Jak ostrożnie przypisać autorowi ukryte założenie?','["Autor zdaje się zakładać, że odbiorcy znają wcześniejszy spór.","Autor bezsprzecznie kłamie.","Wszyscy odbiorcy wszystko wiedzą."]',0,'Zdaje się zakładać сохраняет эпистемическую осторожность.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-quiz','Co w tym kontekście znaczy „wieloznaczność”?','["многозначность","буквальность","считывание намерения"]',0,'„wieloznaczność” oznacza tutaj: многозначность.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-reading-check','Dlaczego protokół nie przypisał poparcia ani sprzeciwu?','["Ogólna ocena pozostała niejednoznaczna","Nagranie zaginęło","Projekt wycofano"]',0,'Текст подчёркивает сохранённую неоднозначность оценки.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-grammar','Jak wyprzedzić mocny kontrargument?','["Można zarzucić tej propozycji wysoki koszt; dlatego porównajmy go z kosztem zaniechania.","Kto się nie zgadza, ten nie rozumie problemu.","Koszt nie istnieje."]',0,'Первая версия признаёт возражение и предлагает критерий сравнения.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-quiz','Co w tym kontekście znaczy „antyteza”?','["антитеза","синтаксический параллелизм","риторический вопрос"]',0,'„antyteza” oznacza tutaj: антитеза.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-reading-check','Jak potraktowano kontrargument przedsiębiorców?','["Uznano koszt i wskazano częściową odpowiedź","Przemilczano go","Nazwano go kłamstwem"]',0,'Возражение признано и связано с переходным фондом.',3,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-grammar','Która korekta rozbraja dwuznaczność zdania «Rozmawiała z siostrą Anny»?','["Rozmawiała z Anną, która ma siostrę.","Rozmawiała z nią.","Rozmawiała z siostrą."]',0,'Переформулировка прямо указывает референта и устраняет конкурирующее прочтение.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-quiz','Co w tym kontekście znaczy „dosłowność”?','["буквальность","считывание намерения","добавочный смысл"]',0,'„dosłowność” oznacza tutaj: буквальность.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-reading-check','Co mogłoby zamknąć pole interpretacji?','["Prośba o doprecyzowanie","Kolejne domysły","Usunięcie protokołu"]',0,'Автор прямо указывает на запрос уточнения.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-grammar','Która puenta wynika z argumentu, zamiast tylko brzmieć efektownie?','["Skoro pilotaż zmniejszył liczbę błędów, rozszerzenie wymaga teraz niezależnej ewaluacji.","Przyszłość należy do odważnych.","Nie ma innej drogi."]',0,'Вывод связан с данными и одновременно обозначает следующий критерий проверки.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-quiz','Co w tym kontekście znaczy „paralelizm składniowy”?','["синтаксический параллелизм","риторический вопрос","пуанте, заключительный акцент"]',0,'„paralelizm składniowy” oznacza tutaj: синтаксический параллелизм.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-reading-check','Na czym polegała nowa puenta?','["Na propozycji pilotażu z kryteriami oceny","Na wezwaniu do natychmiastowej decyzji","Na pytaniu bez odpowiedzi"]',0,'Финал стал проверяемым предложением.',4,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-grammar','Jak zachować niedopowiedzenie bez dopisywania faktu?','["Wypowiedź pozostawia otwarte pytanie o motywy rozmówcy.","Rozmówca kierował się wyłącznie zazdrością.","Motyw nie ma żadnego znaczenia."]',0,'Открытый вопрос описывает недосказанность, не выдавая интерпретацию за факт.',5,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-quiz','Co w tym kontekście znaczy „odczytanie intencji”?','["считывание намерения","добавочный смысл","следовать из контекста"]',0,'„odczytanie intencji” oznacza tutaj: считывание намерения.',5,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c21-reading-check','Jaka zasada podsumowuje tekst?','["Nie formułować twierdzenia mocniejszego niż dane","Zawsze wybierać najbardziej krytyczne odczytanie","Ignorować kontekst"]',0,'Финальный абзац формулирует именно этот принцип.',5,true);
insert into public.questions(lesson_id,prompt,options,correct,explanation,position,is_active) values ('c22-grammar','Gdzie pojawia się pozorny dylemat?','["Albo przyjmiemy projekt dziś, albo miasto nigdy się nie rozwinie.","Możemy wdrożyć projekt, zmienić go albo odrzucić.","Decyzja wymaga danych o kosztach."]',0,'Первая реплика искусственно сводит множество возможностей к двум крайностям.',5,true);
