insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c21-tekst','c2-semantic-precision','Смысловая точность','Различаем пресуппозицию, импликатуру и намеренную недосказанность','C2',16,'🧠','["Podczas posiedzenia komisji przewodnicząca powiedziała, że projekt „nie jest pozbawiony zalet”. Część słuchaczy uznała to za ostrożną pochwałę, inni — za elegancki sposób okazania rezerwy. Sama warstwa dosłowna nie rozstrzygała sporu.","Językoznawczyni zaproponowała więc rozdzielenie trzech poziomów. Zdanie stwierdzało istnienie zalet, presuponowało wspólną znajomość projektu, a przez nietypowo powściągliwą formę mogło implikować, że zastrzeżenia przeważają nad aprobatą.","Nagranie ujawniło dodatkowy szczegół: chwilę wcześniej rozmówcy dyskutowali o wysokich kosztach. Ten kontekst wzmacniał krytyczne odczytanie, lecz nadal go nie dowodził. Badaczka zaznaczyła różnicę między wnioskiem dobrze uzasadnionym a jedyną możliwą interpretacją.","W protokole zapisano zatem, że przewodnicząca dostrzegła zalety projektu, a jej ogólna ocena pozostała niejednoznaczna. Nie przypisano jej ani poparcia, ani sprzeciwu. Dopiero prośba o doprecyzowanie mogłaby zamknąć pole interpretacji.","Przykład pokazał, że zaawansowana kompetencja nie polega na odgadywaniu ukrytej prawdy. Polega raczej na ważeniu sygnałów, nazywaniu stopnia pewności i powstrzymaniu się od twierdzenia mocniejszego niż dostępne dane."]','{"presupozycja":{"lemma":"presupozycja","translation":"пресуппозиция","part_of_speech":"rzeczownik"},"implikatura":{"lemma":"implikatura","translation":"импликатура, подразумеваемый смысл","part_of_speech":"rzeczownik"},"niedopowiedzenie":{"lemma":"niedopowiedzenie","translation":"недосказанность","part_of_speech":"rzeczownik"},"wieloznaczność":{"lemma":"wieloznaczność","translation":"многозначность","part_of_speech":"rzeczownik"},"dosłowność":{"lemma":"dosłowność","translation":"буквальность","part_of_speech":"rzeczownik"},"odczytanie intencji":{"lemma":"odczytanie intencji","translation":"считывание намерения","part_of_speech":"wyrażenie rzeczownikowe"},"sens naddany":{"lemma":"sens naddany","translation":"добавочный смысл","part_of_speech":"wyrażenie rzeczownikowe"},"wynikać z kontekstu":{"lemma":"wynikać z kontekstu","translation":"следовать из контекста","part_of_speech":"wyrażenie czasownikowe"},"uchylić się od odpowiedzi":{"lemma":"uchylić się od odpowiedzi","translation":"уклониться от ответа","part_of_speech":"wyrażenie czasownikowe"},"zasugerować mimochodem":{"lemma":"zasugerować mimochodem","translation":"намекнуть вскользь","part_of_speech":"wyrażenie czasownikowe"},"doprecyzować zakres":{"lemma":"doprecyzować zakres","translation":"уточнить границы","part_of_speech":"wyrażenie czasownikowe"},"rozbroić dwuznaczność":{"lemma":"rozbroić dwuznaczność","translation":"устранить двусмысленность","part_of_speech":"wyrażenie czasownikowe"},"pozostawić pole do interpretacji":{"lemma":"pozostawić pole do interpretacji","translation":"оставить пространство для интерпретации","part_of_speech":"fraza"},"czytać między wierszami":{"lemma":"czytać między wierszami","translation":"читать между строк","part_of_speech":"frazeologizm"},"nie bez znaczenia":{"lemma":"nie bez znaczenia","translation":"не без значения","part_of_speech":"fraza modalna"},"pragmatyka":{"lemma":"pragmatyka","translation":"прагматика","part_of_speech":"rzeczownik"},"adresat zbiorowy":{"lemma":"adresat zbiorowy","translation":"коллективный адресат","part_of_speech":"wyrażenie rzeczownikowe"},"warstwa deklaratywna":{"lemma":"warstwa deklaratywna","translation":"декларативный слой","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c21-reading-check"}',57,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('c22-tekst','c2-rhetorical-strategy','Риторическая стратегия','Управляем перспективой, темпом и силой аргумента без манипуляции','C2',16,'🎙️','["Zespół rzeczniczki przygotował wystąpienie o ograniczeniu ruchu w centrum. Pierwsza wersja zaczynała się od alarmujących danych, po których natychmiast padało pytanie retoryczne: „Czy naprawdę stać nas na bezczynność?”. Tekst był dynamiczny, lecz dzielił odbiorców na zwolenników działania i rzekomych obrońców chaosu.","Redaktorka rozpoznała w tej konstrukcji pozorny dylemat. Zaproponowała odwrócenie perspektywy: zamiast przeciwstawiać działanie bezczynności, należało porównać trzy warianty zmian, ich koszty i skutki dla różnych grup mieszkańców.","Nowa wersja zachowała rytm dzięki paralelizmowi: „sprawdźmy dane, sprawdźmy koszty, sprawdźmy konsekwencje”. Potem wyprzedzała kontrargument przedsiębiorców, przyznając, że reorganizacja dostaw będzie kosztowna, i wskazując fundusz przejściowy jako częściową odpowiedź.","Najważniejsza zmiana dotyczyła puenty. Zamiast hasła o odwadze pojawił się wniosek o półrocznym pilotażu z publicznymi kryteriami oceny. Retoryczny punkt ciężkości przesunął się z moralnej presji na możliwość wspólnego sprawdzenia rozwiązania.","Wystąpienie stało się mniej widowiskowe, ale bardziej odporne na krytykę. Rzeczniczka nie zrezygnowała z perswazji: użyła kompozycji, gradacji i antytezy. Podporządkowała je jednak uczciwości argumentacyjnej, dzięki czemu odbiorcy mogli ocenić nie tylko siłę słów, lecz także jakość racji."]','{"figura retoryczna":{"lemma":"figura retoryczna","translation":"риторическая фигура","part_of_speech":"wyrażenie rzeczownikowe"},"punkt ciężkości":{"lemma":"punkt ciężkości","translation":"смысловой центр","part_of_speech":"wyrażenie rzeczownikowe"},"gradacja":{"lemma":"gradacja","translation":"градация","part_of_speech":"rzeczownik"},"antyteza":{"lemma":"antyteza","translation":"антитеза","part_of_speech":"rzeczownik"},"paralelizm składniowy":{"lemma":"paralelizm składniowy","translation":"синтаксический параллелизм","part_of_speech":"wyrażenie rzeczownikowe"},"pytanie retoryczne":{"lemma":"pytanie retoryczne","translation":"риторический вопрос","part_of_speech":"wyrażenie rzeczownikowe"},"puenta":{"lemma":"puenta","translation":"пуанте, заключительный акцент","part_of_speech":"rzeczownik"},"wyprzedzić kontrargument":{"lemma":"wyprzedzić kontrargument","translation":"предвосхитить контраргумент","part_of_speech":"wyrażenie czasownikowe"},"stopniować napięcie":{"lemma":"stopniować napięcie","translation":"наращивать напряжение","part_of_speech":"wyrażenie czasownikowe"},"przesunąć akcent":{"lemma":"przesunąć akcent","translation":"сместить акцент","part_of_speech":"wyrażenie czasownikowe"},"zawęzić tezę":{"lemma":"zawęzić tezę","translation":"сузить тезис","part_of_speech":"wyrażenie czasownikowe"},"odwrócić perspektywę":{"lemma":"odwrócić perspektywę","translation":"изменить перспективу","part_of_speech":"wyrażenie czasownikowe"},"pozorny dylemat":{"lemma":"pozorny dylemat","translation":"ложная дилемма","part_of_speech":"wyrażenie rzeczownikowe"},"chwyt erystyczny":{"lemma":"chwyt erystyczny","translation":"эристический приём","part_of_speech":"wyrażenie rzeczownikowe"},"uczciwość argumentacyjna":{"lemma":"uczciwość argumentacyjna","translation":"честность аргументации","part_of_speech":"wyrażenie rzeczownikowe"},"rytm wypowiedzi":{"lemma":"rytm wypowiedzi","translation":"ритм высказывания","part_of_speech":"wyrażenie rzeczownikowe"},"hierarchia racji":{"lemma":"hierarchia racji","translation":"иерархия доводов","part_of_speech":"wyrażenie rzeczownikowe"},"odporność argumentu":{"lemma":"odporność argumentu","translation":"устойчивость аргумента","part_of_speech":"wyrażenie rzeczownikowe"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-31","level_status":"curriculum_target","comprehension_lesson_id":"c22-reading-check"}',58,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
